const T_SUSPECT := 1.5; const T_FREEZE := 4.0; const T_DEAD := 7.0; const T_DEAD_2ND := 9.0; const T_GIVEUP := 18.0
var host_term := 0; var host_sid := 0; var last_host_rx := 0.0
func _on_packet(sender:int, hdr:Dictionary):
  if hdr.term < host_term: return  # 旧房主的消息一律丢弃
  if hdr.term > host_term: _adopt_new_host(hdr.term, sender)
  if sender == host_sid: last_host_rx = Time.get_ticks_msec()/1000.0
func _process(_d):
  var gap = Time.get_ticks_msec()/1000.0 - last_host_rx
  match state:
    IN_GAME: if gap > T_SUSPECT: state = SUSPECT
    SUSPECT: if gap > T_FREEZE: _freeze(); _broadcast_host_lost()
    FROZEN: if gap > T_DEAD and my_rank()==0: _promote_self()
            elif gap > T_DEAD_2ND and my_rank()==1 and not rank0_alive(): _promote_self()
            elif gap > T_GIVEUP: _fallback_a1()
